# frozen_string_literal: true

require "rails_helper"

RSpec.describe Timekeeping::MetricsClient do
  # The metrics body holds every company's counts, so the client must never
  # call the endpoint without the service identity.
  it "metrics client refuses to call Timekeeping when the service token is empty" do
    env_before = ENV.to_h.slice("TIMEKEEPING_BASE_URL", "TIMEKEEPING_SERVICE_TOKEN")
    ENV["TIMEKEEPING_BASE_URL"] = "http://timekeeping.test"
    metrics = WebMock.stub_request(:get, "http://timekeeping.test/internal/v1/metrics")
                     .to_return(status: 200, body: "{}", headers: { "Content-Type" => "application/json" })

    ["", nil].each do |token|
      ENV["TIMEKEEPING_SERVICE_TOKEN"] = token
      expect { described_class.new.fetch }.to raise_error(Timekeeping::MetricsClient::Error)
    end

    expect(metrics).not_to have_been_requested
  ensure
    %w[TIMEKEEPING_BASE_URL TIMEKEEPING_SERVICE_TOKEN].each { |key| ENV[key] = env_before[key] }
  end
end

RSpec.describe Timekeeping::MetricsClient, "unusable answers" do
  let(:unusable_metrics_url) { "http://timekeeping.test/internal/v1/metrics" }
  let(:unusable_metrics_client) do
    described_class.new(base_url: "http://timekeeping.test", service_token: "service-#{SecureRandom.hex(24)}")
  end

  # The alert task reports the monolith's own alerts when a read fails with
  # this class's Error, so no other failure may escape the client.
  it "raises its own Error for a 200 body without window_seconds, such as one from an older Timekeeping" do
    complete = { "window_seconds" => 300, "latency_bucket_bounds_ms" => [300], "overflow_bucket" => "inf",
                 "companies" => [], "outbox_lag" => [] }
    WebMock.stub_request(:get, unusable_metrics_url)
           .to_return({ status: 200, body: JSON.generate(complete.except("window_seconds")) },
                      { status: 200, body: JSON.generate(complete) })

    expect { unusable_metrics_client.fetch }
      .to raise_error(Timekeeping::MetricsClient::Error, "Timekeeping metrics body is missing fields")
    expect(unusable_metrics_client.fetch).to eq(complete)
  end

  it "raises its own Error for a 200 body whose companies list is null" do
    body = { "window_seconds" => 300, "latency_bucket_bounds_ms" => [300], "overflow_bucket" => "inf",
             "companies" => nil, "outbox_lag" => [] }
    WebMock.stub_request(:get, unusable_metrics_url).to_return(status: 200, body: JSON.generate(body))

    expect { unusable_metrics_client.fetch }
      .to raise_error(Timekeeping::MetricsClient::Error, "Timekeeping metrics body is missing fields")
  end

  it "raises its own Error for a garbled HTTP answer" do
    WebMock.stub_request(:get, unusable_metrics_url).to_raise(Net::HTTPBadResponse)

    expect { unusable_metrics_client.fetch }
      .to raise_error(Timekeeping::MetricsClient::Error, "Timekeeping metrics read failed: Net::HTTPBadResponse")
  end
end

RSpec.describe Timekeeping::MetricsClient do
  it "metrics client sends the service token only as a bearer header and keeps it out of a refusal error" do
    env_before = ENV.to_h.slice("TIMEKEEPING_BASE_URL", "TIMEKEEPING_SERVICE_TOKEN")
    token = "service-#{SecureRandom.hex(24)}"
    ENV["TIMEKEEPING_BASE_URL"] = "http://timekeeping.test"
    ENV["TIMEKEEPING_SERVICE_TOKEN"] = token
    refused = WebMock.stub_request(:get, "http://timekeeping.test/internal/v1/metrics")
                     .with(headers: { "Authorization" => "Bearer #{token}" })
                     .to_return(status: 401, body: JSON.generate("reason" => "unauthorized"),
                                headers: { "Content-Type" => "application/json" })

    error = nil
    begin
      described_class.new.fetch
    rescue Timekeeping::MetricsClient::Error => e
      error = e
    end

    expect(refused).to have_been_requested.once
    expect(WebMock).to have_requested(:get, "http://timekeeping.test/internal/v1/metrics")
      .with { |request| request.uri.query.nil? && !request.uri.to_s.include?(token) }
    expect(error).to be_a(Timekeeping::MetricsClient::Error)
    expect(error.message).not_to include(token)
    expect(error.full_message).not_to include(token)
  ensure
    %w[TIMEKEEPING_BASE_URL TIMEKEEPING_SERVICE_TOKEN].each { |key| ENV[key] = env_before[key] }
  end
end
